mapper.select:

where h.is_delete = 0
and h.tournament_id = #{tournamentId}
and h.season_id = #{seasonId}
and h.honor_category_id = #{honorCategoryId}
and c.honor_code = #{honorCode}
and c.honor_scope = #{honorScope}
and c.recipient_type = #{recipientType}
and h.team_id = #{teamId}
and h.player_id = #{playerId}
and h.display_status = #{displayStatus}

    and (h.honor_title like concat('%', #{keyword}, '%')
         or t.team_name like concat('%', #{keyword}, '%')
         or p.real_name like concat('%', #{keyword}, '%')
         or p.game_nickname like concat('%', #{keyword}, '%'))

order by h.display_order, h.award_date desc, h.id desc

select id, tournament_id, season_id, honor_category_id, team_id, player_id, match_id,
       honor_title, honor_subtitle, honor_value, award_date, cover_file_id, source_type, source_id,
       display_status, display_order, remark, create_time, update_time, is_delete
from basket_honor_record
where is_delete = 0 and season_id = #{seasonId} and honor_category_id = #{honorCategoryId}
  and display_status <> 3
and team_id = #{teamId}
and team_id is null
and player_id = #{playerId}
and player_id is null
and id <> #{excludeId}
limit 1

select count(1) from basket_honor_record
where is_delete = 0 and season_id = #{seasonId} and honor_category_id = #{honorCategoryId}
  and display_status <> 3
and team_id = #{teamId}
and team_id is null
and player_id = #{playerId}
and player_id is null
and id <> #{excludeId}

mapper.update:
update basket_honor_record
set display_status = #{toStatus}, update_time = now()
where id = #{id} and is_delete = 0 and display_status = #{fromStatus}

update basket_honor_record set is_delete = 1, update_time = now()
where id = #{id} and is_delete = 0 and display_status in
#{s}
